//! Builds the function-history database from a kernel git repository.
//!
//! Each release tag is walked in order. File blobs are parsed once and cached
//! by object id, so files unchanged between releases cost nothing. Per
//! (function, file, signature), consecutive versions are compacted into one
//! span row.
//!
//! Each release also gets a macro scope (see `extract::scope`), used to find
//! functions generated by macro invocations and, for macros that replaced
//! functions, what they call instead (see `generate`).

use crate::generate::{self, Calls, Generated};
use anyhow::{Context, Result};
use extract::scope::Scope;
use extract::{FileFacts, Function, Kind};
use git2::{ObjectType, Oid, Repository, TreeWalkMode, TreeWalkResult};
use rayon::prelude::*;
use rusqlite::{Connection, params};
use std::collections::{BTreeSet, HashMap, HashSet};
use std::path::Path;
use std::sync::Arc;
use std::time::Instant;

/// Top-level directories that hold userspace or build tooling, not kernel code.
const EXCLUDED_DIRS: &[&str] = &["tools/", "scripts/", "Documentation/", "samples/", "usr/"];

pub const SCHEMA: &str = "
CREATE TABLE versions (
    ord INTEGER PRIMARY KEY,
    tag TEXT NOT NULL UNIQUE,
    commit_time INTEGER NOT NULL
);
CREATE TABLE signatures (
    id INTEGER PRIMARY KEY,
    kind TEXT NOT NULL,
    return_type TEXT NOT NULL,
    params TEXT NOT NULL,          -- JSON [{\"ty\":..,\"name\":..}]
    is_static INTEGER NOT NULL,
    is_inline INTEGER NOT NULL,
    attributes TEXT NOT NULL,      -- JSON [\"__init\", ...]
    body TEXT,                     -- replacement text, for kind = 'Macro'
    generated_by TEXT,             -- macro invocation that generates the function
    origin TEXT                    -- files of the macro definitions that decide it exists
);
CREATE TABLE defs (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    file TEXT NOT NULL,
    UNIQUE (name, file)
);
-- A def had a given signature for versions first_ord..=last_ord.
-- `lines` holds the definition line for each of those versions, comma separated.
CREATE TABLE spans (
    def_id INTEGER NOT NULL REFERENCES defs(id),
    sig_id INTEGER NOT NULL REFERENCES signatures(id),
    first_ord INTEGER NOT NULL,
    last_ord INTEGER NOT NULL,
    lines TEXT NOT NULL,
    -- For a generated function: the deciding macro definitions as file:line,
    -- as of first_ord. Line numbers move with unrelated edits, so they are
    -- kept here rather than in the signature.
    origin TEXT
);
CREATE INDEX spans_def ON spans(def_id);
CREATE INDEX spans_sig ON spans(sig_id);
-- For a macro: real functions its expansion calls, for versions first_ord..=last_ord.
-- primary_calls receive the macro's arguments; other_calls do not. JSON arrays.
CREATE TABLE macro_targets (
    def_id INTEGER NOT NULL REFERENCES defs(id),
    first_ord INTEGER NOT NULL,
    last_ord INTEGER NOT NULL,
    primary_calls TEXT NOT NULL,
    other_calls TEXT NOT NULL
);
CREATE INDEX macro_targets_def ON macro_targets(def_id);
";

/// Failed builds are retried after 6 hours, then 12, and not after the third attempt.
const MAX_ATTEMPTS: u32 = 3;
const FIRST_RETRY_SECS: u64 = 6 * 3600;

#[derive(Debug, PartialEq, Eq)]
enum Retry {
    /// Build now; this is attempt number `attempt`.
    Go { attempt: u32 },
    /// A recent attempt on the same releases failed; try again after `until`.
    Wait { until: u64 },
    /// Every allowed attempt failed; only --force builds again.
    GiveUp { attempts: u32 },
}

/// Decides whether to build, given the marker a failed attempt left behind
/// (`attempts=N last=UNIX` followed by the release tags it tried).
fn retry_decision(marker: Option<&str>, releases: &str, now: u64, force: bool) -> Retry {
    let previous = marker.and_then(|m| {
        let (header, tried) = m.split_once('\n')?;
        let mut fields = header.split(' ');
        let attempts: u32 = fields.next()?.strip_prefix("attempts=")?.parse().ok()?;
        let last: u64 = fields.next()?.strip_prefix("last=")?.parse().ok()?;
        (tried == releases).then_some((attempts, last))
    });
    match previous {
        None => Retry::Go { attempt: 1 },
        Some((attempts, _)) if force => Retry::Go { attempt: attempts + 1 },
        Some((attempts, _)) if attempts >= MAX_ATTEMPTS => Retry::GiveUp { attempts },
        Some((attempts, last)) => {
            let until = last + FIRST_RETRY_SECS * 2u64.pow(attempts.saturating_sub(1));
            if now < until {
                Retry::Wait { until }
            } else {
                Retry::Go { attempt: attempts + 1 }
            }
        }
    }
}

pub struct Options {
    /// Oldest release to include, as (major, minor).
    pub since: (u32, u32),
    /// Stop after this many releases (for quick experiments).
    pub limit: Option<usize>,
    /// Replace an existing database even if the new one fails `verify::check_replacement`.
    pub force: bool,
}

/// Mainline release tags (`vX.Y`, no `-rc`) at or after `since`, oldest first.
pub fn release_tags(repo: &Repository, since: (u32, u32)) -> Result<Vec<(String, (u32, u32))>> {
    let mut tags: Vec<_> = repo
        .tag_names(Some("v*"))?
        .iter()
        .filter_map(|t| {
            let t = t.ok()??;
            let (major, minor) = t.strip_prefix('v')?.split_once('.')?;
            let v = (major.parse().ok()?, minor.parse().ok()?);
            (v >= since).then(|| (t.to_string(), v))
        })
        .collect();
    tags.sort_by_key(|(_, v)| *v);
    Ok(tags)
}

/// One function definition as seen in a single version.
#[derive(Clone)]
struct Occurrence {
    name: String,
    sig_id: i64,
    line: u32,
    kind: Kind,
}

/// A parsed file blob. `facts.functions` has moved into `occurrences`.
struct Blob {
    occurrences: Vec<Occurrence>,
    facts: FileFacts,
}

/// Cached expansions are keyed by file, blob and index: the same content at
/// another path resolves `#include "..."` differently.
type MemoKey = (Arc<str>, Oid, usize);

struct OpenSpan {
    first_ord: i64,
    lines: Vec<u32>,
    origin: Option<String>,
}

pub fn build(repo_path: &Path, db_path: &Path, opts: &Options) -> Result<()> {
    // libgit2 refuses repositories owned by another user (git's safe.directory
    // check). That check stops git from running commands a hostile repository's
    // config asks for; kfh only reads objects, and libgit2 runs no hooks or
    // config commands, so the owner of the clone does not matter here (in a
    // container it often differs from the user kfh runs as).
    // SAFETY: called before any repository is opened, from a single thread.
    unsafe { git2::opts::set_verify_owner_validation(false)? };
    let repo = Repository::open(repo_path).with_context(|| format!("opening {}", repo_path.display()))?;
    let mut tags = release_tags(&repo, opts.since)?;
    if let Some(limit) = opts.limit {
        tags.truncate(limit);
    }
    anyhow::ensure!(
        !tags.is_empty(),
        "no release tags found at or after v{}.{}",
        opts.since.0,
        opts.since.1
    );

    // One build per database at a time: a manual run and the scheduled one
    // would otherwise write the same temporary file.
    let lock = std::fs::File::options()
        .create(true)
        .truncate(false)
        .write(true)
        .open(db_path.with_extension("db.lock"))
        .with_context(|| format!("creating the lock next to {}", db_path.display()))?;
    match lock.try_lock() {
        Ok(()) => {}
        Err(std::fs::TryLockError::WouldBlock) => {
            eprintln!("another build of {} is running; nothing to do", db_path.display());
            return Ok(());
        }
        Err(std::fs::TryLockError::Error(e)) => return Err(e.into()),
    }

    // A full build takes hours; skip it when the database already has exactly
    // these releases.
    if !opts.force && db_path.exists() {
        let wanted: Vec<&str> = tags.iter().map(|(t, _)| t.as_str()).collect();
        if crate::verify::release_tags(db_path)? == wanted {
            eprintln!(
                "{} already covers {}..{}; nothing to do",
                db_path.display(),
                wanted[0],
                wanted[wanted.len() - 1]
            );
            return Ok(());
        }
    }

    // A build that did not finish (it failed, was rejected, or was killed)
    // leaves a marker naming the releases it tried and how often. Retrying the
    // same input on every hourly run would cost hours each time, so retries
    // back off and stop after a few attempts.
    let attempt_path = db_path.with_extension("db.attempt");
    let releases: String = tags.iter().map(|(t, _)| format!("{t}\n")).collect();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)?
        .as_secs();
    let previous = std::fs::read_to_string(&attempt_path).ok();
    let attempts = match retry_decision(previous.as_deref(), &releases, now, opts.force) {
        Retry::Go { attempt } => attempt,
        Retry::Wait { until } => {
            eprintln!(
                "the last build of {}..{} failed; retrying after {} (unix time), see {}",
                tags[0].0,
                tags[tags.len() - 1].0,
                until,
                attempt_path.display()
            );
            return Ok(());
        }
        Retry::GiveUp { attempts } => anyhow::bail!(
            "the build of {}..{} failed {attempts} times; fix the cause and rerun with --force (see {})",
            tags[0].0,
            tags[tags.len() - 1].0,
            attempt_path.display()
        ),
    };
    std::fs::write(&attempt_path, format!("attempts={attempts} last={now}\n{releases}"))?;

    // Build into a temporary file so a failed run never leaves a half-written database.
    let tmp_path = db_path.with_extension("db.tmp");
    let _ = std::fs::remove_file(&tmp_path);
    let mut db = Connection::open(&tmp_path)?;
    db.execute_batch("PRAGMA journal_mode = OFF; PRAGMA synchronous = OFF;")?;
    db.execute_batch(SCHEMA)?;
    let tx = db.transaction()?;

    let mut sig_ids: HashMap<String, i64> = HashMap::new();
    let mut def_ids: HashMap<(String, Arc<str>), i64> = HashMap::new();
    let mut open: HashMap<(i64, i64), OpenSpan> = HashMap::new();
    let mut cache: HashMap<Oid, Arc<Blob>> = HashMap::new();
    let mut gen_memo: HashMap<MemoKey, Arc<Generated>> = HashMap::new();
    let mut calls_memo: HashMap<MemoKey, Arc<Calls>> = HashMap::new();
    let mut ever_functions: HashSet<String> = HashSet::new();
    // (macro def, targets JSON) -> first version.
    let mut open_targets: HashMap<(i64, String), i64> = HashMap::new();

    for (ord, (tag, _)) in tags.iter().enumerate() {
        let ord = ord as i64;
        let started = Instant::now();
        let commit = repo.revparse_single(tag)?.peel_to_commit()?;
        tx.execute(
            "INSERT INTO versions (ord, tag, commit_time) VALUES (?1, ?2, ?3)",
            params![ord, tag, commit.time().seconds()],
        )?;
        let files = source_files(&commit.tree()?)?;

        let mut new_blobs: Vec<Oid> = files
            .iter()
            .map(|(_, oid)| *oid)
            .filter(|oid| !cache.contains_key(oid))
            .collect();
        new_blobs.sort();
        new_blobs.dedup();
        let parsed = parse_blobs(repo_path, &new_blobs)?;
        let parsed_count = parsed.len();

        let mut next_cache = HashMap::with_capacity(files.len());
        for (oid, mut facts) in parsed {
            let occurrences = std::mem::take(&mut facts.functions)
                .into_iter()
                .map(|f| {
                    Ok(Occurrence {
                        name: f.name.clone(),
                        line: f.line,
                        kind: f.kind,
                        sig_id: intern_sig(&tx, &mut sig_ids, &f)?,
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            next_cache.insert(oid, Arc::new(Blob { occurrences, facts }));
        }
        for (_, oid) in &files {
            if let Some(blob) = cache.get(oid) {
                next_cache.entry(*oid).or_insert_with(|| blob.clone());
            }
        }
        cache = next_cache;
        let parse_time = started.elapsed();

        let scope = {
            let refs: Vec<(Arc<str>, &FileFacts)> = files.iter().map(|(p, o)| (p.clone(), &cache[o].facts)).collect();
            Scope::new(&refs)
        };

        // Functions generated by macro invocations, per file.
        let generated: Vec<Vec<(MemoKey, Arc<Generated>, bool)>> = files
            .par_iter()
            .enumerate()
            .map(|(i, (path, oid))| {
                let blob = &cache[oid];
                blob.facts
                    .invocations
                    .iter()
                    .enumerate()
                    .filter(|(_, inv)| scope.is_macro(&inv.name))
                    .map(|(k, inv)| {
                        let key = (path.clone(), *oid, k);
                        let ctx = scope.at(i, inv.line);
                        match gen_memo.get(&key) {
                            Some(g) if g.deps.still_valid(&ctx) => (key, g.clone(), false),
                            _ => (key, Arc::new(generate::generate(&ctx, inv, path)), true),
                        }
                    })
                    .collect()
            })
            .collect();
        let expanded = generated.iter().flatten().filter(|g| g.2).count();

        // (def, sig) -> first line seen in this version.
        let mut current: HashMap<(i64, i64), (u32, Option<String>)> = HashMap::new();
        let mut version_functions: HashSet<String> = HashSet::new();
        let mut generated_count = 0;
        for (i, (path, oid)) in files.iter().enumerate() {
            let gen_fns: Vec<&Function> = generated[i].iter().flat_map(|(_, g, _)| g.functions.iter()).collect();
            // BPF_CALL_n is recorded from its header as a fallback; the
            // expansion, when available, has the real (u64) signature.
            let gen_at: HashSet<(&str, u32)> = gen_fns.iter().map(|f| (f.name.as_str(), f.line)).collect();
            for occ in &cache[oid].occurrences {
                if occ.kind == Kind::BpfCall && gen_at.contains(&(occ.name.as_str(), occ.line)) {
                    continue;
                }
                let def_id = def_id(&tx, &mut def_ids, &occ.name, path)?;
                current.entry((def_id, occ.sig_id)).or_insert((occ.line, None));
                if occ.kind != Kind::Macro {
                    version_functions.insert(occ.name.clone());
                }
            }
            for f in gen_fns {
                let sig_id = intern_sig(&tx, &mut sig_ids, f)?;
                let def_id = def_id(&tx, &mut def_ids, &f.name, path)?;
                current.entry((def_id, sig_id)).or_insert((f.line, f.origin.clone()));
                version_functions.insert(f.name.clone());
                generated_count += 1;
            }
        }
        gen_memo = generated.into_iter().flatten().map(|(k, g, _)| (k, g)).collect();

        let ended: Vec<_> = open.keys().filter(|k| !current.contains_key(k)).copied().collect();
        for key in ended {
            let span = open.remove(&key).expect("key taken from map");
            write_span(&tx, key, &span, ord - 1)?;
        }
        for (key, (line, origin)) in current {
            open.entry(key)
                .or_insert_with(|| OpenSpan {
                    first_ord: ord,
                    lines: Vec::new(),
                    origin,
                })
                .lines
                .push(line);
        }

        // What macros named like a function (now or earlier) call instead.
        ever_functions.extend(version_functions.iter().cloned());
        let jobs: Vec<(usize, usize)> = files
            .iter()
            .enumerate()
            .flat_map(|(i, (_, oid))| {
                let ever = &ever_functions;
                cache[oid]
                    .facts
                    .macros
                    .iter()
                    .enumerate()
                    .filter(move |(_, m)| ever.contains(&m.name))
                    .map(move |(k, _)| (i, k))
            })
            .collect();
        let calls: Vec<(MemoKey, Arc<Calls>)> = jobs
            .par_iter()
            .map(|&(i, k)| {
                let (path, oid) = &files[i];
                let m = &cache[oid].facts.macros[k];
                let key = (path.clone(), *oid, k);
                let ctx = scope.at(i, m.line + 1);
                match calls_memo.get(&key) {
                    Some(c) if c.deps.still_valid(&ctx) => (key, c.clone()),
                    _ => (key, Arc::new(generate::calls(&ctx, scope.macro_def(i, m), m))),
                }
            })
            .collect();
        let mut targets: HashMap<i64, (BTreeSet<String>, BTreeSet<String>)> = HashMap::new();
        for ((path, oid, k), c) in &calls {
            let Some(found) = &c.calls else { continue };
            let name = &cache[oid].facts.macros[*k].name;
            let (primary, also) = generate::classify(found, |n| version_functions.contains(n));
            let entry = targets.entry(def_id(&tx, &mut def_ids, name, path)?).or_default();
            entry.0.extend(primary);
            entry.1.extend(also);
        }
        calls_memo = calls.into_iter().collect();
        let current_targets: HashSet<(i64, String)> = targets
            .into_iter()
            .map(|(def, (primary, also))| {
                let also: Vec<&String> = also.iter().filter(|a| !primary.contains(*a)).collect();
                (def, serde_json::json!([primary, also]).to_string())
            })
            .collect();
        let ended: Vec<_> = open_targets
            .keys()
            .filter(|k| !current_targets.contains(k))
            .cloned()
            .collect();
        for key in ended {
            let first = open_targets.remove(&key).expect("key taken from map");
            write_targets(&tx, &key, first, ord - 1)?;
        }
        for key in current_targets {
            open_targets.entry(key).or_insert(ord);
        }

        eprintln!(
            "{tag:>7}: {} files, {parsed_count} parsed ({:.1}s), {expanded} expanded, {generated_count} generated, {} defs live, {} signatures ({:.1}s)",
            files.len(),
            parse_time.as_secs_f32(),
            open.len(),
            sig_ids.len(),
            started.elapsed().as_secs_f32()
        );
    }

    let last_ord = tags.len() as i64 - 1;
    for (key, span) in &open {
        write_span(&tx, *key, span, last_ord)?;
    }
    for (key, first) in &open_targets {
        write_targets(&tx, key, *first, last_ord)?;
    }
    prune_macros(&tx)?;
    tx.commit()?;
    db.execute_batch("ANALYZE; VACUUM;")?;
    drop(db);
    if !opts.force
        && let Err(e) = crate::verify::check_replacement(&tmp_path, Some(db_path))
    {
        let _ = std::fs::remove_file(&tmp_path);
        return Err(e.context(format!(
            "kept {}: the new database failed its checks",
            db_path.display()
        )));
    }
    std::fs::rename(&tmp_path, db_path)?;
    std::fs::remove_file(&attempt_path)?;
    drop(lock);
    Ok(())
}

/// Keeps a macro only when its name is a real function somewhere in the
/// history: the "function became a macro" case. The kernel has over 100k
/// other function-like macros per release. Every step is index-backed.
fn prune_macros(tx: &rusqlite::Transaction) -> Result<()> {
    let steps = [
        "CREATE TEMP TABLE function_names (name TEXT PRIMARY KEY) WITHOUT ROWID",
        "INSERT OR IGNORE INTO function_names
             SELECT d.name FROM signatures g
             JOIN spans s ON s.sig_id = g.id
             JOIN defs d ON d.id = s.def_id
             WHERE g.kind != 'Macro'",
        "DELETE FROM spans WHERE NOT EXISTS (
             SELECT 1 FROM defs d JOIN function_names f ON f.name = d.name WHERE d.id = spans.def_id)",
        "DELETE FROM defs WHERE NOT EXISTS (SELECT 1 FROM spans WHERE spans.def_id = defs.id)",
        "DELETE FROM signatures WHERE NOT EXISTS (SELECT 1 FROM spans WHERE spans.sig_id = signatures.id)",
        "DELETE FROM macro_targets WHERE NOT EXISTS (SELECT 1 FROM defs WHERE defs.id = macro_targets.def_id)",
        "DROP TABLE function_names",
    ];
    for sql in steps {
        let started = Instant::now();
        tx.execute_batch(sql)?;
        let label: String = sql.split_whitespace().take(3).collect::<Vec<_>>().join(" ");
        eprintln!("  prune: {label} ({:.1}s)", started.elapsed().as_secs_f32());
    }
    Ok(())
}

/// All kernel `.c`/`.h` files in a tree, as (path, blob id).
fn source_files(tree: &git2::Tree) -> Result<Vec<(Arc<str>, Oid)>> {
    let mut files = Vec::new();
    tree.walk(TreeWalkMode::PreOrder, |dir, entry| {
        if dir.is_empty() && entry.kind() == Some(ObjectType::Tree) {
            let name = entry.name().unwrap_or_default();
            if EXCLUDED_DIRS.iter().any(|d| d.trim_end_matches('/') == name) {
                return TreeWalkResult::Skip;
            }
        }
        if entry.kind() == Some(ObjectType::Blob)
            && let Some(name) = entry.name().ok().filter(|n| n.ends_with(".c") || n.ends_with(".h"))
        {
            files.push((Arc::from(format!("{dir}{name}")), entry.id()));
        }
        TreeWalkResult::Ok
    })?;
    Ok(files)
}

/// Parses blobs in parallel; each worker thread opens its own repository handle.
fn parse_blobs(repo_path: &Path, oids: &[Oid]) -> Result<Vec<(Oid, FileFacts)>> {
    oids.par_iter()
        .map_init(
            || Repository::open(repo_path),
            |repo, oid| {
                let repo = repo.as_ref().map_err(|e| anyhow::anyhow!("opening repository: {e}"))?;
                let blob = repo.find_blob(*oid)?;
                Ok((*oid, extract::analyze(blob.content())))
            },
        )
        .collect()
}

fn intern_sig(tx: &rusqlite::Transaction, ids: &mut HashMap<String, i64>, f: &Function) -> Result<i64> {
    let kind = format!("{:?}", f.kind);
    let params_json = serde_json::to_string(&f.params)?;
    let attrs_json = serde_json::to_string(&f.attributes)?;
    let origin = origin_files(f.origin.as_deref());
    let key = format!(
        "{kind}\0{}\0{params_json}\0{}\0{}\0{attrs_json}\0{:?}\0{:?}\0{:?}",
        f.return_type, f.is_static, f.is_inline, f.body, f.generated_by, origin
    );
    if let Some(&id) = ids.get(&key) {
        return Ok(id);
    }
    tx.execute(
        "INSERT INTO signatures (kind, return_type, params, is_static, is_inline, attributes, body, generated_by, origin)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![
            kind,
            f.return_type,
            params_json,
            f.is_static,
            f.is_inline,
            attrs_json,
            f.body,
            f.generated_by,
            origin
        ],
    )?;
    let id = tx.last_insert_rowid();
    ids.insert(key, id);
    Ok(id)
}

fn write_span(tx: &rusqlite::Transaction, (def_id, sig_id): (i64, i64), span: &OpenSpan, last_ord: i64) -> Result<()> {
    let lines: Vec<String> = span.lines.iter().map(u32::to_string).collect();
    tx.execute(
        "INSERT INTO spans (def_id, sig_id, first_ord, last_ord, lines, origin) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![def_id, sig_id, span.first_ord, last_ord, lines.join(","), span.origin],
    )?;
    Ok(())
}

fn def_id(
    tx: &rusqlite::Transaction,
    ids: &mut HashMap<(String, Arc<str>), i64>,
    name: &str,
    path: &Arc<str>,
) -> Result<i64> {
    if let Some(&id) = ids.get(&(name.to_string(), path.clone())) {
        return Ok(id);
    }
    tx.execute("INSERT INTO defs (name, file) VALUES (?1, ?2)", params![name, &**path])?;
    let id = tx.last_insert_rowid();
    ids.insert((name.to_string(), path.clone()), id);
    Ok(id)
}

fn write_targets(tx: &rusqlite::Transaction, (def_id, json): &(i64, String), first: i64, last: i64) -> Result<()> {
    let [primary, also]: [Vec<String>; 2] = serde_json::from_str(json)?;
    tx.execute(
        "INSERT INTO macro_targets (def_id, first_ord, last_ord, primary_calls, other_calls) VALUES (?1, ?2, ?3, ?4, ?5)",
        params![def_id, first, last, serde_json::to_string(&primary)?, serde_json::to_string(&also)?],
    )?;
    Ok(())
}

/// An origin without line numbers: `a.h:12, a.h:40 (note)` -> `a.h (note)`.
fn origin_files(origin: Option<&str>) -> Option<String> {
    let origin = origin?;
    let mut out = String::with_capacity(origin.len());
    let mut chars = origin.chars().peekable();
    while let Some(c) = chars.next() {
        if c == ':' && chars.peek().is_some_and(char::is_ascii_digit) {
            while chars.peek().is_some_and(char::is_ascii_digit) {
                chars.next();
            }
            continue;
        }
        out.push(c);
    }
    let (list, note) = match out.find(" (") {
        Some(i) => out.split_at(i),
        None => (out.as_str(), ""),
    };
    let (prefix, list) = list
        .strip_prefix("all except ")
        .map_or(("", list), |l| ("all except ", l));
    let mut files: Vec<&str> = Vec::new();
    for f in list.split(", ") {
        if !files.contains(&f) {
            files.push(f);
        }
    }
    Some(format!("{prefix}{}{note}", files.join(", ")))
}

#[cfg(test)]
mod tests {
    use super::origin_files;

    #[test]
    fn failed_builds_back_off_then_give_up() {
        use super::{Retry, retry_decision};
        let rel = "v7.1\nv7.2\n";
        let marker = |n: u32, last: u64| format!("attempts={n} last={last}\n{rel}");
        assert_eq!(retry_decision(None, rel, 100, false), Retry::Go { attempt: 1 });
        // Another set of releases (a new tag arrived): start over.
        assert_eq!(
            retry_decision(Some(&marker(3, 0)), "v7.1\n", 100, false),
            Retry::Go { attempt: 1 }
        );
        let h = 3600;
        assert_eq!(
            retry_decision(Some(&marker(1, 0)), rel, 5 * h, false),
            Retry::Wait { until: 6 * h }
        );
        assert_eq!(
            retry_decision(Some(&marker(1, 0)), rel, 6 * h, false),
            Retry::Go { attempt: 2 }
        );
        assert_eq!(
            retry_decision(Some(&marker(2, 0)), rel, 11 * h, false),
            Retry::Wait { until: 12 * h }
        );
        assert_eq!(
            retry_decision(Some(&marker(2, 0)), rel, 12 * h, false),
            Retry::Go { attempt: 3 }
        );
        assert_eq!(
            retry_decision(Some(&marker(3, 0)), rel, 1000 * h, false),
            Retry::GiveUp { attempts: 3 }
        );
        assert_eq!(
            retry_decision(Some(&marker(3, 0)), rel, 0, true),
            Retry::Go { attempt: 4 }
        );
        // A corrupt marker does not block building.
        assert_eq!(retry_decision(Some("garbage"), rel, 0, false), Retry::Go { attempt: 1 });
    }

    #[test]
    fn origin_files_drop_line_numbers() {
        assert_eq!(
            origin_files(Some(
                "arch/x86/include/asm/syscall_wrapper.h:110, arch/x86/include/asm/syscall_wrapper.h:223"
            ))
            .as_deref(),
            Some("arch/x86/include/asm/syscall_wrapper.h")
        );
        assert_eq!(
            origin_files(Some(
                "include/linux/syscalls.h:245 (architectures without their own definition)"
            ))
            .as_deref(),
            Some("include/linux/syscalls.h (architectures without their own definition)")
        );
        assert_eq!(
            origin_files(Some("all except a/b.h:1, c/d.h:2")).as_deref(),
            Some("all except a/b.h, c/d.h")
        );
        assert_eq!(origin_files(None), None);
    }
}
